pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 calls, uint256 amount) public {
        // Bound calls to a reasonable number to avoid OutOfGas while still allowing overflow path
        calls = bound(calls, 1, 5000);
        amount = bound(amount, 0, type(uint256).max / calls);

        // Record initial state and balance
        uint256 initialDeposits = c.depositsCount();
        uint256 initialBalance = address(c).balance;

        // Send `calls` calls with amount wei each, checking for reverts
        bool allSucceed = true;
        vm.deal(address(this), amount * calls);
        for (uint256 i = 0; i < calls; i++) {
            try c{value: amount}() {
                // call succeeded
            } catch {
                allSucceed = false;
            }
        }

        // After all calls, the invariants:
        // 1. If all calls succeeded, depositsCount must have increased by calls
        // 2. If any call reverted, it must be the last iteration (overflow) and depositsCount still >= initialDeposits
        if (allSucceed) {
            assertTrue(c.depositsCount() == initialDeposits + calls);
        } else {
            // Overflows trigger revert; depositsCount should be >= initial (never decreased)
            assertTrue(c.depositsCount() >= initialDeposits);
        }
        // Contract balance should equal or exceed initial balance (if sends succeed, balance increases)
        assertTrue(address(c).balance >= initialBalance);
    }
}

