import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint8 count0, uint8 count1) public {
        vm.assume(amount <= address(this).balance);
        // Perform first batch of deposits
        for (uint256 i = 0; i < count0; i++) {
            vm.deal(address(this), amount);
            (bool ok, ) = address(c).call{value: amount}("");
            vm.assume(ok); // ensure the call succeeded for the reference
        }
        uint256 preCount = c.depositsCount();
        // Perform second batch of deposits
        for (uint256 i = 0; i < count1; i++) {
            vm.deal(address(this), amount);
            (bool ok, ) = address(c).call{value: amount}("");
            vm.assume(ok);
        }
        uint256 postCount = c.depositsCount();
        // Invariant: depositsCount never decreases and strictly increases when at least one deposit succeeded
        assertTrue(postCount > preCount || (count1 == 0 && postCount == preCount));
    }
}

