pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 startingCount, uint256 value, uint8 callsAfter) public {
        // Bound startingCount to [0, type(uint256).max - 1] to avoid immediate overflow on first call
        startingCount = bound(startingCount, 0, type(uint256).max - 1);
        // Set depositsCount to startingCount by calling receive startingCount times
        for (uint256 i = 0; i < startingCount; i++) {
            vm.deal(address(this), 1 wei);
            (bool success, ) = address(c).call{value: 1 wei}("");
            require(success, "Setup failed");
        }
        // Bound callsAfter to [1, 255] to ensure at least one call and avoid excessive loops
        callsAfter = uint8(bound(uint256(callsAfter), 1, 255));
        // Fuzzed value for each call, bound to 1 wei minimum so call doesn't revert for that reason
        value = uint256(bound(value, 1, type(uint256).max));
        // If startingCount + callsAfter would exceed max, skip to avoid known overflow revert
        vm.assume(startingCount <= type(uint256).max - callsAfter);
        // Attempt callsAfter receive calls
        bool allSucceeded = true;
        for (uint256 i = 0; i < callsAfter; i++) {
            vm.deal(address(this), value);
            (bool success, ) = address(c).call{value: value}("");
            if (!success) {
                allSucceeded = false;
                break;
            }
        }
        // Reference: if we are below max before calls, all callsAfter invocations succeed and depositsCount increases by callsAfter
        // Mutant: check always true, so count increments until overflow, then reverts; thus allSucceeded may be false or count less than expected
        uint256 expectedCount = startingCount + callsAfter;
        assertTrue(allSucceeded && c.depositsCount() == expectedCount);
    }
}

