import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint128 value, uint256 preCalls) public {
        // Bound preCalls to a safe range that won't use all gas, but allow overflow reachable
        vm.assume(preCalls <= 100);
        vm.assume(value > 0);

        // Set up depositsCount to a high near-max value to make overflow possible in buggy version
        // But only for the bug scenario; we need an invariant that the reference always satisfies.
        // We cannot set private state directly, so we only use public interactions.
        // Instead, we observe the property: after each receive, depositsCount strictly increases.
        // If we cannot set depositsCount to near max, the fuzzer will not trigger overflow in buggy version unless we make many calls.
        // Since we are allowed to call receive many times, let's call it preCalls times to advance depositsCount.
        vm.deal(address(this), (value + 1) * preCalls);
        for (uint i = 0; i < preCalls; i++) {
            c.receive{value: value}();
        }

        uint beforeCount = c.depositsCount();
        vm.deal(address(this), value);
        c.receive{value: value}();
        uint afterCount = c.depositsCount();

        // Invariant: depositsCount must strictly increase by 1 after a successful receive
        assertTrue(afterCount == beforeCount + 1);
    }
}

